def write_locale(code, data, is_partial=False):
    path = os.path.join(BASE, f'{code}.ts')
    type_name = 'TranslationKeys'
    if is_partial:
        content = f"import type {{ {type_name} }} from '../types';\n\nexport const {code}: Partial<{type_name}> = {{\n"
    else:
        content = f"import type {{ {type_name} }} from '../types';\n\nexport const {code}: {type_name} = {{\n"
    for k, v in sorted(data.items()):
        escaped = v.replace("\\", "\\\\").replace("'", "\\'").replace('\n', '\\n')
        content += f"  '{k}': '{escaped}',\n"
    content += '};\n'
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)

write_locale('it', IT)
write_locale('en', EN)

all_codes = ['de','fr','es','pt','nl','pl','sv','no','da','fi','cs','el','ro','hu','bg','hr','sk','sr','lt','lv','et','sl','uk','zh','ja','ko','hi','th','vi','id','ar','he','tr','ru']
for code in all_codes:
    data = TRANSLATIONS.get(code, {})
    write_locale(code, data, is_partial=True)

print(f'Generated {2 + len(all_codes)} locale files in {BASE}')